create function public.is_friend_of(uuid_target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = uuid_target and addressee_id = auth.uid())
       or (requester_id = auth.uid() and addressee_id = uuid_target)
       and status = 'accepted'
  );
$$;

create function public.enforce_friendship_immutable()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending' then
      raise exception 'new friendships must be pending';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.status = 'accepted' then
      raise exception 'accepted friendships are immutable';
    end if;

    if new.requester_id <> old.requester_id
       or new.addressee_id <> old.addressee_id then
      raise exception 'friendship participants cannot be changed';
    end if;

    if new.status <> 'accepted' then
      raise exception 'only pending requests can be updated';
    end if;

    return new;
  end if;

  return new;
end;
$$;

alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create policy friendships_select_involved
  on public.friendships
  for select
  to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy friendships_insert_requester_pending
  on public.friendships
  for insert
  to authenticated
  with check (requester_id = auth.uid() and status = 'pending');

create policy friendships_update_addressee_accept
  on public.friendships
  for update
  to authenticated
  using (addressee_id = auth.uid() and status = 'pending')
  with check (status = 'accepted');

create policy friendships_delete_involved
  on public.friendships
  for delete
  to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

create trigger friendships_enforce_immutable
  before insert or update on public.friendships
  for each row
  execute function public.enforce_friendship_immutable();

create policy posts_select_visible
  on public.posts
  for select
  to anon, authenticated
  using (
    audience = 'public'
    or author_id = auth.uid()
    or public.is_friend_of(author_id)
  );

create policy posts_insert_own
  on public.posts
  for insert
  to authenticated
  with check (author_id = auth.uid());

create policy posts_update_own
  on public.posts
  for update
  to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy posts_delete_own
  on public.posts
  for delete
  to authenticated
  using (author_id = auth.uid());
