create function public.prevent_request_schema_change()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'open' then
      raise exception 'new requests must be open';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.id <> new.id
       or old.unit_id <> new.unit_id
       or old.created_by <> new.created_by
       or old.description <> new.description then
      raise exception 'only status can be changed on a request';
    end if;

    if not public.is_building_staff((select building_id from public.units where id = new.unit_id)) then
      raise exception 'only building staff can change request status';
    end if;

    return new;
  end if;

  return new;
end;
$$;

