grant select on table public.auctions to authenticated;
grant select on table public.bids to authenticated;
grant usage, select on sequence public.bids_id_seq to authenticated;

create policy "auctions_select_authenticated"
  on public.auctions
  for select
  to authenticated
  using (true);

create policy "bids_select_own_or_seller"
  on public.bids
  for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions
      where id = bids.auction_id
        and seller_id = auth.uid()
    )
  );

create function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_current_user uuid := auth.uid();
  v_auction public.auctions;
  v_new_id bigint;
  v_new_highest numeric;
begin
  if v_current_user is null then
    raise exception 'not authenticated';
  end if;

  select *
    into v_auction
    from public.auctions
   where id = p_auction_id
   for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = v_current_user then
    raise exception 'cannot bid on own auction';
  end if;

  if p_amount <= v_auction.starting_price then
    raise exception 'bid must be above starting price';
  end if;

  if v_auction.highest_bid is null then
    if p_amount <= v_auction.starting_price then
      raise exception 'bid must be above starting price';
    end if;
  else
    if p_amount <= v_auction.highest_bid + v_auction.min_increment then
      raise exception 'bid must exceed current highest bid by at least the minimum increment';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_current_user, p_amount)
  returning id into v_new_id;

  update public.auctions
     set highest_bid = p_amount,
         highest_bidder = v_current_user
   where id = p_auction_id;

  select p_amount;
end;
$$;

revoke all on function public.place_bid(bigint, numeric) from public, anon;
grant execute on function public.place_bid(bigint, numeric) to authenticated, service_role;
