  v_uid uuid := auth.uid();
  v_auction public.auctions;
  v_current_high numeric;
  v_min_increment numeric;
  v_requirement numeric;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at <= pg_catalog.now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'cannot bid on own auction';
  end if;

  select coalesce(highest_bid, 0) into v_current_high from public.auctions where id = p_auction_id;
  select min_increment into v_min_increment from public.auctions where id = p_auction_id;

  if p_amount <= v_current_high then
    raise exception 'bid too low';
  end if;

  v_requirement := v_current_high + v_min_increment;
  if p_amount < v_requirement then
    raise exception 'bid too low';
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_uid, p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  return p_amount;
end
$$;

